SELECT COUNT(*) AS N_ROWS
     , SUM(CASE WHEN RDXSRCT_CODE IS NULL OR TRIM(CAST(RDXSRCT_CODE AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSRCT_CODE AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSRCT_CODE
     , SUM(CASE WHEN RDXSET_ID IS NULL OR TRIM(CAST(RDXSET_ID AS STRING)) = '' OR LOWER(TRIM(CAST(RDXSET_ID AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXSET_ID
     , SUM(CASE WHEN COLL_ID IS NULL OR TRIM(CAST(COLL_ID AS STRING)) = '' OR LOWER(TRIM(CAST(COLL_ID AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_COLL_ID
     , SUM(CASE WHEN RDXCUST_NO IS NULL OR TRIM(CAST(RDXCUST_NO AS STRING)) = '' OR LOWER(TRIM(CAST(RDXCUST_NO AS STRING))) = 'null' THEN 1 ELSE 0 END) AS BAD_RDXCUST_NO
FROM `${hivevar:environment}_PERSIST_RDXSRC_DB`.RDXSRC_TBL_RDXSRC_RDXSET_IMP_SPC_CARD
WHERE DL_DATA_DT = '${hivevar:dl_data_dt}';
